      {
        title: 'What flux bootstrap does and the cluster path it generates',
        image: '/diagrams/devops/flux-2-bootstrap.png',
        description: `The diagram traces the bootstrap sequence and the repository layout it produces. Bootstrap is one command that performs four distinct actions, and understanding that it is four actions rather than an installer is the whole point.

The four actions:

1. Install the controllers. The CLI renders the GitOps Toolkit manifests for the requested version and applies them to the cluster, creating the flux-system namespace, the CRDs, the controller Deployments, and the RBAC.

2. Commit those same manifests to Git. Under the --path you specify, bootstrap writes a flux-system directory containing the rendered installation.

3. Create a GitRepository and a Kustomization pointing at that path. This is the self-reference. Flux is now configured to reconcile the directory that contains Flux.

4. Configure repository authentication. Depending on flags, that is a deploy key registered with the provider, or a token stored as a Secret named flux-system in the flux-system namespace.

The generated cluster path:

  clusters/my-cluster/flux-system/
  ├── gotk-components.yaml   # all GOTK controllers, CRDs, RBAC — the rendered install
  ├── gotk-sync.yaml         # the GitRepository + Kustomization that point back here
  └── kustomization.yaml     # a Kustomize overlay listing both, plus your patches

The gotk- prefix stands for GitOps Toolkit. The kustomization.yaml is not incidental — it is the supported customization seam. Because Flux reconciles this path like any other, patches you add there are applied to Flux own Deployments on the next reconciliation.

Self-management is the property that follows. Flux is reconciling a Kustomization whose source contains the manifests that define Flux. Three consequences:

Upgrades become commits. Regenerate gotk-components.yaml at a newer version, commit, push, and Flux upgrades itself. No cluster access needed.
Customizations survive. Increasing source-controller concurrency or adding a toleration is a patch in kustomization.yaml, reconciled like anything else, rather than a kubectl edit that the next install overwrites.
Disaster recovery is re-running bootstrap. Point the same command at a new empty cluster and the same repository path; Flux installs, reconciles the flux-system path, then reconciles everything else that path references. The cluster rebuilds itself from Git.

Bootstrap is idempotent. Re-running it is the normal way to change version, components, or authentication.

Customization via kustomization.yaml patches:

\`\`\`yaml
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
resources:
  - gotk-components.yaml
  - gotk-sync.yaml
patches:
  - target:                                # every Flux controller
      labelSelector: app.kubernetes.io/part-of=flux
    patch: |
      - op: add
        path: /spec/template/spec/tolerations
        value:
          - key: node-role.kubernetes.io/control-plane
            operator: Exists
            effect: NoSchedule
  - target:                                # one controller by name
      kind: Deployment
      name: source-controller
    patch: |
      - op: add
        path: /spec/template/spec/containers/0/args/-
        value: --concurrent=5
\`\`\`

Multi-cluster layout. --path is what scopes a cluster. One repository holds every cluster, and each bootstrap targets its own directory:

  clusters/
  ├── staging/flux-system/
  ├── prod-eu/flux-system/
  └── prod-us/flux-system/

Each cluster reconciles only its own path, so a change under prod-eu cannot reach prod-us. Shared platform configuration lives outside clusters/ and is pulled in by Kustomizations each cluster path chooses to declare, which is how you get common baselines with per-cluster opt-in.

The contrast with flux install: flux install applies the same controllers and stops. Nothing is written to Git, no GitRepository or Kustomization is created, and Flux does not manage itself. It is appropriate for a throwaway test cluster or as a manifest generator via flux install --export. It is not appropriate for anything you intend to keep.`,
      }
