    introduction: `There are two ways to get Flux onto a cluster, and the difference between them is the difference between a demo and a production installation. flux install applies the GitOps Toolkit controllers to the cluster and stops. flux bootstrap does that, then commits the same manifests into a Git repository and configures Flux to reconcile the directory it just wrote. After bootstrap, Flux is managing Flux.

That self-reference is the design point, not a curiosity. Bootstrap writes three files under the --path you choose: gotk-components.yaml, the rendered controller installation including CRDs and RBAC; gotk-sync.yaml, containing the GitRepository and Kustomization that point back at this same directory; and kustomization.yaml, a Kustomize overlay listing both, which is where your customizations go. The gotk prefix is GitOps Toolkit. Because Flux reconciles that path on an interval like any other Kustomization, upgrading Flux becomes a commit, customizing controller flags becomes a patch, and rebuilding a destroyed cluster becomes re-running the same bootstrap command against the same path.

Bootstrap is idempotent by design. Re-running it is not a recovery action, it is the normal way to change the Flux version, add components, or rotate credentials. The Flux documentation treats bootstrap as declarative-first and disaster-resilient for exactly this reason.

Provider subcommands exist for the common hosts: github, gitlab, bitbucket-server, gitea, azure devops, aws codecommit, google cloud source repositories, oracle VBS, plus a generic git that works against anything reachable over SSH or HTTPS. The provider-specific variants do extra work — they can create the repository if it does not exist, grant team access, and register the deploy key through the provider API — which is why they want a token with administration permission even when the resulting sync credential is a read-only deploy key. flux bootstrap git does none of that and expects you to have created the repository and installed the key yourself, which makes it the right choice for locked-down and air-gapped environments.

The authentication decision is the one with lasting consequences. --token-auth is the default and stores the provider token as a Secret named flux-system in the flux-system namespace, meaning a live provider credential now sits in the cluster. --token-auth=false makes Flux generate an SSH key pair, keep the private half as that Secret, and register the public half as a repository deploy key that is read-only unless you pass --read-write-key. The deploy key is the narrower credential and the better default; the read-write variant is only needed when the image automation controllers must push commits back. For GitHub specifically, flux create secret githubapp supports GitHub App authentication with short-lived installation tokens, though that command is still marked as in preview.

The rest of the lifecycle follows from self-management. Upgrades are a regenerated gotk-components.yaml committed to Git, or a re-run of bootstrap with a newer CLI, verified with flux check. Air-gapped installs mirror the controller images to a private registry with crane and pass --registry, --registry-creds, and --image-pull-secret. Uninstall is flux uninstall, which removes the controllers, CRDs, and toolkit custom resources but deliberately leaves every workload Flux was reconciling still running in the cluster. Interviewers probe that last detail because engineers routinely assume uninstalling Flux tears down their applications, and it does not.`,
