        question: 'What is the difference between flux install and flux bootstrap, and why does self-management matter?',
        answer: `flux install deploys the controllers and stops.

\`\`\`bash
flux install
flux install --components-extra=image-reflector-controller,image-automation-controller
flux install --export > gotk-components.yaml
\`\`\`

It creates the flux-system namespace, the CRDs, the controller Deployments, and the RBAC. If a previous version is present it performs an in-place upgrade. What it does not do: write anything to Git, create a GitRepository, or create a Kustomization. Flux is running but Flux is not managed by Flux. The --export form is genuinely useful — it prints the manifests to stdout for committing, or for piping into kubectl apply --dry-run=client -f- as a validation step.

flux bootstrap does four things in one command.

\`\`\`bash
export GITHUB_TOKEN=<token>

flux bootstrap github \\
  --owner=my-org \\
  --repository=fleet-infra \\
  --branch=main \\
  --path=clusters/prod-eu \\
  --version=v2.7.0 \\
  --components-extra=image-reflector-controller,image-automation-controller \\
  --token-auth=false
\`\`\`

It installs the controllers; commits gotk-components.yaml, gotk-sync.yaml, and kustomization.yaml under clusters/prod-eu/flux-system; creates a GitRepository plus a Kustomization pointing at that same path; and configures authentication, here by generating an SSH key and registering the public half as a deploy key.

Why self-management matters, concretely:

Upgrades need no cluster access. Regenerate gotk-components.yaml at a newer version, commit, push. Flux reconciles the path, sees new controller images, and rolls itself forward. An engineer with repository write access and no kubeconfig can upgrade the fleet.

Customizations survive. Adding --concurrent=5 to source-controller is a patch in kustomization.yaml. Because Flux reconciles that path, the patch is reapplied every interval. Do the same thing with kubectl edit and it is reverted on the next pass — which is a very common first Flux surprise.

Disaster recovery is one command. The cluster is gone. Provision a new empty one, run the identical bootstrap command against the same repository and path. Flux installs, reconciles flux-system, then reconciles every Kustomization that path declares, and the workloads come back. Under flux install you would be rebuilding by hand.

Idempotency makes it operable. Re-running bootstrap is the routine way to change version, add --components-extra, or rotate a credential. It is not a repair operation.

The one-sentence version for an interview: flux install is an installer, flux bootstrap makes Flux a GitOps-managed application like everything else in the cluster, and only the second one is a production answer.`,
