        description: `The flux binary is a thin client. It has no daemon, no server component, and no state of its own. Every subcommand either writes a Flux custom resource to the Kubernetes API, reads one back, annotates one, or renders manifests locally. Understanding which of those four things a command does is the difference between using Flux correctly and fighting it.

Commands that change the cluster directly (use sparingly in a GitOps setup):

  flux bootstrap github|gitlab|bitbucket-server|git ...
    Installs the GitOps Toolkit controllers, commits the component manifests into a
    Git repository under a cluster path, and creates the GitRepository plus
    Kustomization that make Flux manage its own installation. Idempotent: running it
    again upgrades the controllers by updating the committed manifests.

  flux install
    Installs the controllers without any Git repository. Useful for local clusters and
    CI, but the cluster is then not self-managed and will not upgrade itself.

  flux uninstall
    Removes controllers, CRDs, and the flux-system namespace.

  flux create <kind> <name> ...
    Generates a Flux CRD and applies it. flux create source git, flux create
    kustomization, flux create helmrelease, flux create source oci, flux create
    source helm, flux create source bucket, flux create image repository,
    flux create image policy, flux create alert, flux create receiver, flux create
    secret git, flux create tenant.

  flux delete <kind> <name>
    Deletes the object. Also imperative.

Commands that read state:

  flux get all -A                       every Flux object with ready status
  flux get all -A --status-selector ready=false     only what is broken
  flux get sources git|oci|helm|bucket|chart
  flux get kustomizations -A
  flux get helmreleases -A
  flux stats -A                         object counts, ready counts, and cumulative
                                        artifact storage per source type
  flux tree kustomization flux-system   the inventory: every object the Kustomization
                                        owns, recursively through child Kustomizations
  flux tree kustomization flux-system --compact    Flux objects only
  flux trace deployment/podinfo         reverse lookup: object to Kustomization to
                                        source to Git commit

Commands that annotate (nudge the controller):

  flux reconcile source git flux-system
  flux reconcile kustomization podinfo
  flux reconcile kustomization podinfo --with-source
  flux reconcile helmrelease podinfo --with-source
  flux suspend kustomization podinfo
  flux resume kustomization podinfo

  These do not apply anything themselves. flux reconcile sets the annotation
  reconcile.fluxcd.io/requestedAt to the current timestamp on the object; the
  controller sees the generation change and reconciles immediately instead of
  waiting for spec.interval, then the CLI blocks until the object reports ready.
  flux suspend sets spec.suspend: true, and flux resume clears it.

Commands that never touch the cluster in a mutating way:

  flux build kustomization my-app --path ./apps/my-app
    Fetches the in-cluster Kustomization spec, applies its transformations
    (postBuild substitution, targetNamespace, patches) to your local directory, and
    prints the resulting multi-doc YAML to stdout. --dry-run skips substitutions
    sourced from Secrets and ConfigMaps so it works without cluster credentials for
    those objects.

  flux diff kustomization my-app --path ./apps/my-app
    Builds the same way, then runs a server-side dry-run apply and prints the diff.
    Exit code 0 means no drift, 1 means differences found, greater than 1 means error.
    That exit code is what makes it usable as a CI gate on pull requests.

  flux <kind> ... --export
    Emits the generated CRD as YAML on stdout instead of applying it. This is the
    GitOps-correct form of every flux create command.

Commands for debugging:

  flux check --pre                      Kubernetes version and prerequisites, no
                                        cluster components required
  flux check                            controller health and installed versions
  flux logs -A --level=error            formatted controller logs, filtered
  flux logs --kind=Kustomization --name=podinfo -n default --follow
  flux events --for Kustomization/podinfo
  flux events --for HelmRelease/podinfo --types warning -w

The mental model to carry into an interview: flux create and flux delete are imperative escape hatches; flux reconcile, suspend, and resume are annotations, not applies; flux build and flux diff are local renderers; and flux trace, tree, logs, events, and stats are the read path you live in during an incident.`,
