      'Move every per-cluster scalar (region, base domain, environment name, replica count) out of the manifests into a cluster-vars ConfigMap referenced by spec.postBuild.substituteFrom, so apps/base stays identical across the fleet',
      'For each tenant, generate the namespace, ServiceAccount, and RoleBinding as code (flux create tenant --with-namespace=... --export is a starting point) and commit them to the platform-admin repository, never to the tenant repository',
