      'Enabling --default-service-account without first adding spec.serviceAccountName to every existing tenant Kustomization — reconciliation stops fleet-wide because everything falls back to an account with no permissions',
      'Leaning on postBuild substitution for structural differences that belong in a Kustomize overlay, until the base manifests are unreadable placeholder soup and no one can tell what production actually runs',
      'Claiming namespace-per-tenant is hard multi-tenancy — shared nodes, shared API server, and cluster-scoped CRDs and admission webhooks mean a determined tenant with pod-security latitude still has escape paths',
